import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { StreamingResponse } from "@/registry/erbium/blocks/streaming-response";
import type { Meta, StoryObj } from "@storybook/react";
import OverviewExample from "./variants/overview";

import MarkdownExample from "./variants/markdown";

import ActionsExample from "./variants/actions";

import StatesExample from "./variants/states";

import CustomUiExample from "./variants/custom-ui";


const name = "streaming-response";

const meta = {
  component: StreamingResponse,
  parameters: {
    docs: { description: { component: componentDocumentation(name) } },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof StreamingResponse>;

export default { ...meta, title: "Blocks/Streaming Response",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(name, "overview") },
      source: { code: "import { useCallback, useEffect } from "react";
import { StreamingResponse, useTextStream } from "@/registry/erbium/blocks/streaming-response";
import { Button } from "@/registry/erbium/ui/button";
import { simulateStream } from "../../streaming";

const reply = `## Retry with backoff

Retry only requests that are **safe to repeat**, and wait longer after each failure:

\`\`\`ts
const retry = async <T>(request: () => Promise<T>, attempts = 3): Promise<T> => {
  try {
    return await request();
  } catch (error) {
    if (attempts <= 1) throw error;
    await new Promise((resolve) => setTimeout(resolve, 2 ** (4 - attempts) * 250));
    return retry(request, attempts - 1);
  }
};
\`\`\`

| Attempt | Wait before it |
| ------: | -------------: |
|       1 |           none |
|       2 |         500 ms |
|       3 |       1,000 ms |

Add random *jitter* when many clients can fail at once.
`;

export default function StreamingResponseExample() {
  const { error, start, status, stop, text } = useTextStream();
  const busy = status === "pending" || status === "streaming";

  const ask = useCallback(() => {
    void start((signal) => simulateStream(reply, { signal }));
  }, [start]);

  useEffect(() => {
    ask();
  }, [ask]);

  return (
    <div className="grid w-full max-w-xl gap-group">
      <Button
        className="justify-self-start"
        variant="outline"
        size="sm"
        onClick={busy ? stop : ask}
      >
        {busy ? "Stop" : "Replay"}
      </Button>
      <StreamingResponse text={text} status={status} error={error?.message} />
    </div>
  );
}
" },
    },
  },
  render: OverviewExample,
};

export const Markdown: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(name, "markdown") },
      source: { code: "import { StreamingResponse, StreamingResponseContent } from "@/registry/erbium/blocks/streaming-response";

const reply = `# Release checklist

Text can be **bold**, *italic*, ~~struck through~~ or \`inline code\`, and can link to
[another page](/docs/introduction) or [another site](https://example.com).

## Steps

1. Run the tests
2. Build the packages
   - types
   - JavaScript

- [x] Changelog written
- [ ] Version tagged

> Publish from a clean checkout, so nothing uncommitted ships.

> [!WARNING]
> A published version cannot be replaced.

\`\`\`ts title="release.ts"
const version: string = "1.4.0";

export const tag = (name = version) => \`v\${name}\`;
\`\`\`

\`\`\`diff
- "version": "1.3.0"
+ "version": "1.4.0"
\`\`\`

| Package | Size | Status |
| :------ | ---: | :----: |
| core    | 4 kB |  ready |
| react   | 9 kB |  ready |

---

The build time grows roughly as $O(n \\log n)$.[^1]

$
\\sum_{i=1}^{n} i = \\frac{n(n+1)}{2}
$

[^1]: Measured on the packages above.
`;

export default function StreamingResponseMarkdownExample() {
  return (
    <StreamingResponse className="max-w-xl" text={reply}>
      <StreamingResponseContent math />
    </StreamingResponse>
  );
}
" },
    },
  },
  render: MarkdownExample,
};

